#!/usr/bin/env bash
# Copyright (c) 2026 Erick Bourgeois, mediatore
# SPDX-License-Identifier: Apache-2.0
#
# What the egress gateway VM image must carry, and must not (ADR-0028 decisions 8 and 10,
# ADR-0027 decisions 1 and 5), checked inside the built image with a container runtime.
# Runs in CI on every pull request and on the build host with `make gateway-image-check`.
# Boots nothing: the live proof is a gateway VM.
set -euo pipefail

IMAGE=${1:?usage: check.sh <image>}
CLI=${CONTAINER_CLI:-docker}
PLUGIN_SHA=$(sed -n 's/.*plugin_checksum = "\([0-9a-f]*\)".*/\1/p' "$(dirname "$0")/../spire/agent.conf")
[ -n "$PLUGIN_SHA" ] || { echo "image/spire/agent.conf carries no plugin_checksum"; exit 1; }

run() { "$CLI" run --rm --entrypoint sh "$IMAGE" -c "$1"; }

fail=0
check() { # <what> <shell>
  if run "$2" >/dev/null 2>&1; then echo "✓ $1"; else echo "✗ $1"; fail=1; fi
}

echo "checking $IMAGE"
check "the one mediatore binary at the pinned path, static, with the gateway role" \
  'test -x /usr/bin/mediatore && /usr/bin/mediatore gateway --help >/dev/null && ! ldd /usr/bin/mediatore 2>/dev/null | grep -q "=>"'
check "Envoy at the pinned version, runs, linked against what the image has" \
  'test -x /usr/bin/envoy && /usr/bin/envoy --version | grep -q 1.40.2 && ! ldd /usr/bin/envoy | grep -q "not found"'
check "no binary under /usr/local (the persistent partition mounts over it)" \
  '! find /usr/local/bin /usr/local/sbin -type f 2>/dev/null | grep -q .'
check "the SPIRE agent in the rootfs" \
  'test -x /usr/bin/spire-agent && /usr/bin/spire-agent --version 2>&1 | grep -q "[0-9]\.[0-9]"'
check "the TPM attestor plugin at the path agent.conf names, with the checksum it pins" \
  "echo '$PLUGIN_SHA  /usr/lib/spire/tpm_attestor_agent' | sha256sum -c - >/dev/null"
check "nftables, for the host table (ADR-0027 decision 5)" 'nft --version >/dev/null'
check "the render script, the authorizer's start script and the six templates" \
  'test -x /usr/libexec/mediatore-gateway/render && test -x /usr/libexec/mediatore-gateway/authorizer-start && for t in envoy/gateway.yaml.in envoy/relay.yaml.in envoy/inject.yaml.in nftables.conf.in network.in authorizer.in; do test -f /usr/share/mediatore-gateway/$t || exit 1; done'
check "the examples render every template, so the documented env is complete" \
  'cd /usr/share/mediatore-gateway && for t in envoy/gateway.yaml.in envoy/relay.yaml.in envoy/inject.yaml.in nftables.conf.in network.in authorizer.in; do /usr/libexec/mediatore-gateway/render $t - env.example vm.env.example >/dev/null || exit 1; done'
check "the rendered data plane, relay and inject Envoy are bootstraps Envoy accepts" \
  'cd /usr/share/mediatore-gateway && mkdir -p /tmp/r && for b in gateway relay inject; do /usr/libexec/mediatore-gateway/render envoy/$b.yaml.in /tmp/r/$b.yaml env.example vm.env.example && /usr/bin/envoy --mode validate -c /tmp/r/$b.yaml >/dev/null 2>&1 || exit 1; done'
check "no admin block in any bootstrap (ADR-0028 decision 8)" \
  '! grep -q "^admin:" /usr/share/mediatore-gateway/envoy/gateway.yaml.in /usr/share/mediatore-gateway/envoy/relay.yaml.in /usr/share/mediatore-gateway/envoy/inject.yaml.in'
check "the relay has no SDS and no TLS context (ADR-0027 decision 1: no credential)" \
  '! grep -qiE "sds_config|tls_context|transport_socket" /usr/share/mediatore-gateway/envoy/relay.yaml.in'
check "the relay has three fixed legs: SPIRE, broker and the SPIRE bundle endpoint (ADR-0037), no registry leg (ADR-0063 decision 4), rendered with their ports and the host table admitting all three" \
  'cd /usr/share/mediatore-gateway && mkdir -p /tmp/r && /usr/libexec/mediatore-gateway/render envoy/relay.yaml.in /tmp/r/relay3.yaml env.example vm.env.example && test "$(grep -c "stat_prefix: relay_" /tmp/r/relay3.yaml)" = 3 && grep -q "upstream=bundle" /tmp/r/relay3.yaml && grep -q "name: spire_bundle" /tmp/r/relay3.yaml && ! grep -v "^[[:space:]]*#" /tmp/r/relay3.yaml | grep -qi registry && /usr/libexec/mediatore-gateway/render nftables.conf.in - env.example vm.env.example | grep -q "elements = { 3129, 3130, 3131 }"'
check "the guest agent's allow-list (R-43): /etc/qemu/qemu-ga.conf names the eight commands the hypervisor side sends, and no exec, file write, password or ssh key command" \
  'f=/etc/qemu/qemu-ga.conf; test -f $f && grep -qx "\[general\]" $f && test "$(grep -c "^allow-rpcs=" $f)" -eq 1 && l=$(sed -n "s/^allow-rpcs=//p" $f) && for c in guest-sync-delimited guest-sync guest-ping guest-info guest-file-open guest-file-read guest-file-close guest-network-get-interfaces; do printf "%s\n" "$l" | tr "," "\n" | grep -qx "$c" || exit 1; done && test "$(printf "%s\n" "$l" | tr "," "\n" | wc -l)" -eq 8 && ! grep -v "^#" $f | grep -Eq "guest-exec|guest-file-write|guest-set-user-password|guest-ssh-|block-rpcs|blacklist"'
check "the agent itself reports that allow-list: allow-rpcs is a key this qemu-ga reads, not one it ignores" \
  'qemu-ga --dump-conf | grep "^allow-rpcs=" | grep -q "guest-file-read" && ! qemu-ga --dump-conf | grep "^allow-rpcs=" | grep -Eq "guest-exec|guest-file-write|guest-set-user-password|guest-ssh-"'
check "the four service users, none in the TPM group, the agent in it" \
  'for u in envoy envoy-relay envoy-inject mediatore-gateway; do id "$u" >/dev/null && ! id -nG "$u" | tr " " "\n" | grep -qx tss || exit 1; done && id -nG spire | tr " " "\n" | grep -qx tss'
check "the user systemd-networkd runs as exists, so the table's WireServer row for the DHCP renewal resolves (ADR-0068)" \
  'id -u systemd-network >/dev/null && grep -qx "User=systemd-network" /usr/lib/systemd/system/systemd-networkd.service && grep -q "meta skuid \"systemd-network\" udp sport 68 udp dport 67 accept" /usr/share/mediatore-gateway/nftables.conf.in && grep -q "ip daddr 169.254.169.254 log prefix" /usr/share/mediatore-gateway/nftables.conf.in'
check "the six units installed and enabled, and the inject Envoy's installed and NOT enabled (it is off until a deployment turns it on, ADR-0040)" \
  'for u in spire-agent mediatore-gateway-network mediatore-gateway-nft envoy-gateway envoy-relay mediatore-gateway; do test -f /etc/systemd/system/$u.service && test -L /etc/systemd/system/multi-user.target.wants/$u.service || exit 1; done && test -f /etc/systemd/system/envoy-inject.service && ! test -e /etc/systemd/system/multi-user.target.wants/envoy-inject.service'
check "the units point at the paths the image has" \
  'grep -q "^ExecStart=/usr/bin/envoy -c /run/mediatore-gateway/gateway.yaml" /etc/systemd/system/envoy-gateway.service && grep -q "^ExecStart=/usr/bin/envoy -c /run/mediatore-gateway/relay.yaml" /etc/systemd/system/envoy-relay.service && grep -qx "ExecStart=/usr/libexec/mediatore-gateway/authorizer-start exec /etc/mediatore-gateway/env /etc/mediatore-gateway/vm.env" /etc/systemd/system/mediatore-gateway.service && grep -q "exec) exec /usr/bin/mediatore gateway " /usr/libexec/mediatore-gateway/authorizer-start && ! grep -q "^ExecStart=.*--listen" /etc/systemd/system/mediatore-gateway.service && grep -q "^ExecStart=/usr/sbin/nft -f /run/mediatore-gateway/nftables.conf" /etc/systemd/system/mediatore-gateway-nft.service'
check "all three Envoys unprivileged, no capability, read-only root, no new privileges (ADR-0028 decision 8, ADR-0040 decision 3)" \
  'for u in envoy-gateway envoy-relay envoy-inject; do f=/etc/systemd/system/$u.service; grep -q "^NoNewPrivileges=yes" $f && grep -q "^CapabilityBoundingSet=$" $f && grep -q "^ProtectSystem=strict" $f && grep -q "^PrivateTmp=yes" $f || exit 1; done && grep -q "^User=envoy$" /etc/systemd/system/envoy-gateway.service && grep -q "^User=envoy-relay$" /etc/systemd/system/envoy-relay.service && grep -q "^User=envoy-inject$" /etc/systemd/system/envoy-inject.service'
check "the relay is kept out of /run/spire by its unit (ADR-0027 decision 1)" \
  'grep -q "^InaccessiblePaths=/run/spire" /etc/systemd/system/envoy-relay.service'
check "the inject Envoy (ADR-0040 decision 3) is its own user, reads the agent's socket (unlike the relay), logs at info and is not kept out of /run/spire" \
  'f=/etc/systemd/system/envoy-inject.service; grep -q "^Group=envoy-inject$" $f && grep -q "^ExecStart=/usr/bin/envoy -c /run/mediatore-gateway/inject.yaml --log-level info" $f && grep -q "^Requires=.*spire-agent.service" $f && grep -q "^ReadOnlyPaths=.*/run/spire/sockets" $f && ! grep -q "^InaccessiblePaths" $f'
check "the inject bootstrap: claim mutual TLS, a bare-host route, TLS origination with SNI and a DNS SAN, ext_authz to the inject socket in inject mode, and no header mutation, CONNECT, strip_any_host_port or admin block (ADR-0040 decisions 3 and 4)" \
  'cd /usr/share/mediatore-gateway && r=$(/usr/libexec/mediatore-gateway/render envoy/inject.yaml.in - env.example vm.env.example | grep -v "^[[:space:]]*#") && printf "%s\n" "$r" | grep -q "require_client_certificate: true" && printf "%s\n" "$r" | grep -q "tls_minimum_protocol_version: TLSv1_3" && printf "%s\n" "$r" | grep -q "mode: inject" && printf "%s\n" "$r" | grep -q "failure_mode_allow: false" && printf "%s\n" "$r" | grep -q "suppress_envoy_headers: true" && printf "%s\n" "$r" | grep -q "pipe: { path: /run/mediatore-gateway/inject/inject.sock }" && ! printf "%s\n" "$r" | grep -Eq "request_headers_to_(add|remove)|response_headers_to_add|strip_any_host_port|connect_matcher|upgrade_configs|dynamic_forward_proxy|^admin:" && ! printf "%s\n" "$r" | grep -Eqi "authorization|x-api-key"'
check "no TLS session resumption on either claim listener: no tickets, no session cache (every connection validates the client certificate)" \
  'cd /usr/share/mediatore-gateway && for b in gateway inject; do r=$(/usr/libexec/mediatore-gateway/render envoy/$b.yaml.in - env.example vm.env.example | grep -v "^[[:space:]]*#") && printf "%s\n" "$r" | grep -q "disable_stateless_session_resumption: true" && printf "%s\n" "$r" | grep -q "disable_stateful_session_resumption: true" || exit 1; done'
check "inject is off by default: the example env admits the three relay ports alone; env.inject.example in front of it admits the inject port and changes nothing else (the data plane is on the CHECK socket either way, and the CHECK and INJECT sockets are in two directories)" \
  'cd /usr/share/mediatore-gateway && /usr/libexec/mediatore-gateway/render nftables.conf.in - env.example vm.env.example | grep -q "elements = { 3129, 3130, 3131 } }" && /usr/libexec/mediatore-gateway/render nftables.conf.in - env.inject.example env.example vm.env.example | grep -q "elements = { 3129, 3130, 3131, 3133 } }" && test "$(grep -c "^[A-Z]" env.inject.example)" = 1 && grep -qx "INJECT_PORT_ELEMENT=, 3133" env.inject.example && /usr/libexec/mediatore-gateway/render envoy/gateway.yaml.in /tmp/r-with.yaml env.inject.example env.example vm.env.example && /usr/libexec/mediatore-gateway/render envoy/gateway.yaml.in /tmp/r-without.yaml env.example vm.env.example && cmp -s /tmp/r-with.yaml /tmp/r-without.yaml && c=$(/usr/libexec/mediatore-gateway/render envoy/gateway.yaml.in - env.example vm.env.example | sed -n "s/^ *pipe: { path: \\(.*check\\.sock\\) }$/\\1/p") && i=$(/usr/libexec/mediatore-gateway/render envoy/inject.yaml.in - env.inject.example env.example vm.env.example | sed -n "s/^ *pipe: { path: \\(.*inject\\.sock\\) }$/\\1/p") && test -n "$c" && test -n "$i" && test "$(dirname "$c")" != "$(dirname "$i")"'
check "the system roots the inject Envoy verifies its upstream against exist in the image" \
  'test -s /etc/ssl/certs/ca-certificates.crt'
check "the agent's unit is the gateway's: it requires the gateway's host table, not the pool's" \
  'grep -q "^Requires=mediatore-gateway-nft.service" /etc/systemd/system/spire-agent.service && ! grep -qE "^(Requires|After|Wants)=.*mediatore-host-nft" /etc/systemd/system/spire-agent.service'
check "the sandbox interface file sorts before the base's DHCP catch-all (10- before 20-dhcp)" \
  'grep -q "^ExecStart=.* /run/systemd/network/10-sandbox.network " /etc/systemd/system/mediatore-gateway-network.service && ! grep -q "^ExecStart=.*/[2-9][0-9]-sandbox.network" /etc/systemd/system/mediatore-gateway-network.service'
check "the Envoys require the table and the interface first (fail closed)" \
  'for u in envoy-gateway envoy-relay envoy-inject; do grep -q "^Requires=.*mediatore-gateway-nft.service" /etc/systemd/system/$u.service && grep -q "^Requires=.*mediatore-gateway-network.service" /etc/systemd/system/$u.service || exit 1; done'
check "forwarding off in the image's sysctl (ADR-0028 decision 8)" \
  'grep -qx "net.ipv4.ip_forward = 0" /etc/sysctl.d/99-mediatore-gateway.conf && grep -qx "net.ipv6.conf.all.forwarding = 0" /etc/sysctl.d/99-mediatore-gateway.conf'
check "Yama's ptrace scope and the kernel hardening in the image's sysctl: no MPTCP, no io_uring, kernel addresses and the kernel log restricted, no unprivileged bpf, the BPF JIT hardened" \
  'grep -qx "kernel.yama.ptrace_scope = 1" /etc/sysctl.d/99-mediatore-gateway.conf && for k in "net.mptcp.enabled = 0" "kernel.io_uring_disabled = 2" "kernel.kptr_restrict = 2" "kernel.dmesg_restrict = 1" "kernel.unprivileged_bpf_disabled = 1" "net.core.bpf_jit_harden = 2"; do grep -qx "$k" /etc/sysctl.d/99-mediatore-gateway.conf || exit 1; done'
check "the host table drops input and forward by default and admits the sandbox ports alone" \
  'grep -q "type filter hook input priority filter; policy drop;" /usr/share/mediatore-gateway/nftables.conf.in && grep -q "type filter hook forward priority filter; policy drop;" /usr/share/mediatore-gateway/nftables.conf.in && grep -q "iifname \"@SANDBOX_IF@\" tcp dport @DATA_PORT@" /usr/share/mediatore-gateway/nftables.conf.in && grep -q "ct count over @RELAY_CAP@" /usr/share/mediatore-gateway/nftables.conf.in && grep -q "flags dynamic" /usr/share/mediatore-gateway/nftables.conf.in'
check "no sshd, ssh and the distribution's nftables unit masked" \
  '! command -v sshd && for u in ssh.service ssh.socket nftables.service; do test "$(readlink /etc/systemd/system/$u)" = /dev/null || exit 1; done'
check "no other listener the base shipped (snmpd, lldpd, rpcbind)" \
  '! command -v snmpd && ! command -v lldpd && ! command -v rpcbind'
check "no private key material (banlieue ADR-0108 decision 2)" \
  '! grep -rl "PRIVATE KEY" /etc /usr/share/mediatore /usr/share/mediatore-gateway /var/lib 2>/dev/null | grep -q .'
# The host table's output chain (ADR-0053 decisions 5 and 6). What is read here is the rendered text and the image's users; that the
# kernel refuses what the chain says is the live run's to show.
check "the output chain: policy accept, a jump per service user (the five the table names; the other two skuid matches are WireServer's root and systemd-network rows, ADR-0068), nothing new by the sandbox interface for any user, the broker's address refused to every user the table did not send elsewhere" \
  'cd /usr/share/mediatore-gateway && n=$(/usr/libexec/mediatore-gateway/render nftables.conf.in - env.example vm.env.example | grep -v "^[[:space:]]*#") && printf "%s\n" "$n" | grep -q "type filter hook output priority filter; policy accept;" && printf "%s\n" "$n" | grep -q "^    ct state established,related accept" && for u in mediatore-gateway envoy-relay spire envoy envoy-inject; do printf "%s\n" "$n" | grep -q "^    meta skuid \"$u\" jump output_" || exit 1; done && test "$(printf "%s\n" "$n" | grep -c "meta skuid .* jump output_")" = 5 && test "$(printf "%s\n" "$n" | grep -c "meta skuid ")" = 7 && printf "%s\n" "$n" | grep -q "^    oifname \"enp2s0\" ct state new log prefix \"mediatore-gateway out sandbox: \" counter drop" && printf "%s\n" "$n" | grep -q "^    ip daddr 192.0.2.21 ct state new log prefix \"mediatore-gateway out broker: \" counter drop"'
check "every user the host table names exists in the image, the five service users and systemd-network (ADR-0068) (a name that does not resolve fails the table's load, and with it every listener)" \
  'us=$(sed -n "s/.*meta skuid \"\([a-z-]*\)\".*/\1/p" /usr/share/mediatore-gateway/nftables.conf.in | sort -u) && test "$(printf "%s\n" "$us" | wc -l)" -eq 6 && for u in $us; do id "$u" >/dev/null || exit 1; done'
check "the output chain's allowlists: the authorizer reaches the broker alone, the agent its server alone, the relay its three upstreams alone (no registry, ADR-0063), each by address and port, and each chain ends in a logged, counted drop" \
  'cd /usr/share/mediatore-gateway && n=$(/usr/libexec/mediatore-gateway/render nftables.conf.in - env.example vm.env.example | grep -v "^[[:space:]]*#") && a=$(printf "%s\n" "$n" | sed -n "/chain output_authorizer {/,/^  }/p") && test "$(printf "%s\n" "$a" | grep -c accept)" = 1 && printf "%s\n" "$a" | grep -q "ip daddr 192.0.2.21 tcp dport 443 accept" && printf "%s\n" "$a" | grep -q "log prefix \"mediatore-gateway out authorizer: \" counter drop" && s=$(printf "%s\n" "$n" | sed -n "/chain output_agent {/,/^  }/p") && test "$(printf "%s\n" "$s" | grep -c accept)" = 1 && printf "%s\n" "$s" | grep -q "ip daddr 192.0.2.20 tcp dport 8081 accept" && printf "%s\n" "$s" | grep -q "counter drop" && r=$(printf "%s\n" "$n" | sed -n "/chain output_relay {/,/^  }/p") && test "$(printf "%s\n" "$r" | grep -c accept)" = 3 && for d in "192.0.2.20 tcp dport 8081" "192.0.2.21 tcp dport 443" "192.0.2.20 tcp dport 8443"; do printf "%s\n" "$r" | grep -q "ip daddr $d accept" || exit 1; done && printf "%s\n" "$r" | grep -q "counter drop"'
check "neither Envoy may dial loopback, IPv6, link-local or a control-plane address, whatever a name resolved to; EGRESS_DENY_ELEMENTS adds the operator's ranges and is empty by default (ADR-0053 decision 6)" \
  'cd /usr/share/mediatore-gateway && mkdir -p /tmp/r && n=$(/usr/libexec/mediatore-gateway/render nftables.conf.in - env.example vm.env.example | grep -v "^[[:space:]]*#") && l=$(printf "%s\n" "$n" | sed -n "/chain output_listener {/,/^  }/p") && printf "%s\n" "$l" | grep -q "oif \"lo\" log prefix \"mediatore-gateway out loopback: \" counter drop" && printf "%s\n" "$l" | grep -q "meta nfproto ipv6 log prefix \"mediatore-gateway out ipv6: \" counter drop" && printf "%s\n" "$l" | grep -q "ip daddr @egress_refused log prefix \"mediatore-gateway out refused: \" counter drop" && printf "%s\n" "$n" | grep -q "set egress_refused { type ipv4_addr; flags interval; auto-merge; elements = { 169.254.0.0/16, 192.0.2.20, 192.0.2.20, 192.0.2.21 } }" && printf "%s\n" "$n" | grep "set resolvers" | grep -vq elements && printf "EGRESS_DENY_ELEMENTS=, 10.0.0.0/8, 198.51.100.77\n" > /tmp/r/deny.env && /usr/libexec/mediatore-gateway/render nftables.conf.in - /tmp/r/deny.env env.example vm.env.example | grep -q "192.0.2.21, 10.0.0.0/8, 198.51.100.77 } }"'
check "by default the tunnel Envoy has no loopback exception and reaches the authorizer over a pipe: the example's table renders check_tcp empty and names port 9001 nowhere, its bootstrap dials the CHECK socket and no loopback address (ADR-0053 open question 7)" \
  'cd /usr/share/mediatore-gateway && n=$(/usr/libexec/mediatore-gateway/render nftables.conf.in - env.example vm.env.example | grep -v "^[[:space:]]*#") && printf "%s\n" "$n" | grep -qx "  set check_tcp { type inet_service;  }" && ! printf "%s\n" "$n" | grep -q 9001 && d=$(/usr/libexec/mediatore-gateway/render envoy/gateway.yaml.in - env.example vm.env.example | grep -v "^[[:space:]]*#") && printf "%s\n" "$d" | sed -n "/^    - name: authorizer$/,/^    - name: destinations$/p" | grep -qx "                    pipe: { path: /run/mediatore-gateway/check/check.sock }" && ! printf "%s\n" "$d" | grep -Eq "127\.0\.0\.1|port_value: 9001" && grep -qx "AUTHORIZER_ENDPOINT=pipe: { path: /run/mediatore-gateway/check/check.sock }" env.example && grep -qx "CHECK_TCP_ELEMENTS=" env.example'
check "the one loopback exception there can be is the tunnel Envoy's, to the authorizer's check port, and only for an env file that sets loopback TCP on purpose (both keys): then the set holds that port, and the inject Envoy's chain still has none" \
  'cd /usr/share/mediatore-gateway && mkdir -p /tmp/r && printf "AUTHORIZER_ENDPOINT=socket_address: { address: 127.0.0.1, port_value: 9001 }\nCHECK_TCP_ELEMENTS=elements = { 9001 }\n" > /tmp/r/tcp.env && n=$(/usr/libexec/mediatore-gateway/render nftables.conf.in - /tmp/r/tcp.env env.example vm.env.example | grep -v "^[[:space:]]*#") && printf "%s\n" "$n" | grep -q "set check_tcp { type inet_service; elements = { 9001 } }" && test "$(printf "%s\n" "$n" | grep -c "@check_tcp")" = 1 && printf "%s\n" "$n" | sed -n "/chain output_envoy {/,/^  }/p" | grep -q "oif \"lo\" ip daddr 127.0.0.1 tcp dport @check_tcp accept" && ! printf "%s\n" "$n" | sed -n "/chain output_listener {/,/^  }/p" | grep -q "check_tcp" && /usr/libexec/mediatore-gateway/render envoy/gateway.yaml.in - /tmp/r/tcp.env env.example vm.env.example | grep -qx "                    socket_address: { address: 127.0.0.1, port_value: 9001 }"'
check "the check socket is the data plane's alone: its directory is made by root at 2750 for the authorizer's user and the group envoy before the authorizer starts, the authorizer may write under the runtime directory, the tunnel Envoy runs in that group, and nobody else is in it (no member, no other user with it as primary group); the same for envoy-inject, and the authorizer is in neither" \
  'f=/etc/systemd/system/mediatore-gateway.service && grep -qx "ExecStartPre=+/usr/bin/install -d -m 2750 -o mediatore-gateway -g envoy /run/mediatore-gateway/check" $f && grep -qx "ReadWritePaths=/run/mediatore-gateway" $f && grep -qx "RestrictSUIDSGID=yes" $f && grep -qx "Group=envoy" /etc/systemd/system/envoy-gateway.service && grep -q "^ReadOnlyPaths=.*/run/mediatore-gateway" /etc/systemd/system/envoy-gateway.service && for g in envoy envoy-inject; do test -z "$(getent group $g | cut -d: -f4)" && gid=$(getent group $g | cut -d: -f3) && test -n "$gid" && test "$(cut -d: -f1,4 /etc/passwd | grep ":$gid\$" | cut -d: -f1)" = "$g" || exit 1; done && test "$(id -nG mediatore-gateway)" = mediatore-gateway'
check "the authorizer listens where the data plane dials: the unit's listen argument is read from the same keys, with the same defaults, as Envoy's bootstrap and the host table (the check socket for the example, for an env file that names neither key and with env.inject.example in front; loopback TCP only for one that names both)" \
  'cd /usr/share/mediatore-gateway && mkdir -p /tmp/r && A=/usr/libexec/mediatore-gateway/authorizer-start && s="--check-socket /run/mediatore-gateway/check/check.sock --socket-dir-mode 2750" && test "$($A print env.example vm.env.example)" = "$s" && test "$($A print env.inject.example env.example vm.env.example)" = "$s" && grep -vE "^(AUTHORIZER_ENDPOINT|CHECK_TCP_ELEMENTS)=" env.example > /tmp/r/neither.env && ! grep -qE "^(AUTHORIZER_ENDPOINT|CHECK_TCP_ELEMENTS)=" /tmp/r/neither.env && test "$($A print /tmp/r/neither.env vm.env.example)" = "$s" && for t in envoy/gateway.yaml.in nftables.conf.in authorizer.in; do /usr/libexec/mediatore-gateway/render $t /tmp/r/neither.out /tmp/r/neither.env vm.env.example && /usr/libexec/mediatore-gateway/render $t /tmp/r/example.out env.example vm.env.example && cmp -s /tmp/r/neither.out /tmp/r/example.out || exit 1; done && printf "AUTHORIZER_ENDPOINT=socket_address: { address: 127.0.0.1, port_value: 9001 }\nCHECK_TCP_ELEMENTS=elements = { 9001 }\n" > /tmp/r/tcp.env && test "$($A print /tmp/r/tcp.env /tmp/r/neither.env vm.env.example)" = "--listen 127.0.0.1:9001" && test "$(grep -c "AUTHORIZER_ENDPOINT:-pipe: { path: /run/mediatore-gateway/check/check.sock }@" envoy/gateway.yaml.in authorizer.in | grep -c ":1$")" = 2 && grep -q "@CHECK_TCP_ELEMENTS:-@" nftables.conf.in && grep -q "@CHECK_TCP_ELEMENTS:-@" authorizer.in'
check "an env file updated by half is refused before the authorizer starts, with the reason: loopback TCP in one key and not in the other (either way round, or two ports), an endpoint that is neither the check socket nor 127.0.0.1, and a key written twice is read as the renderer reads it (the first wins); the unit runs that check as an ExecStartPre" \
  'cd /usr/share/mediatore-gateway && mkdir -p /tmp/r && A=/usr/libexec/mediatore-gateway/authorizer-start && grep -vE "^(AUTHORIZER_ENDPOINT|CHECK_TCP_ELEMENTS)=" env.example > /tmp/r/neither.env && no() { printf "$1" > /tmp/r/half.env; ! $A check /tmp/r/half.env /tmp/r/neither.env vm.env.example 2>/tmp/r/half.err && grep -q "$2" /tmp/r/half.err && ! $A print /tmp/r/half.env /tmp/r/neither.env vm.env.example 2>/dev/null | grep -q .; } && no "AUTHORIZER_ENDPOINT=socket_address: { address: 127.0.0.1, port_value: 9001 }\n" "CHECK_TCP_ELEMENTS () is not" && no "AUTHORIZER_ENDPOINT=socket_address: { address: 127.0.0.1, port_value: 9001 }\nCHECK_TCP_ELEMENTS=\n" "CHECK_TCP_ELEMENTS () is not" && no "CHECK_TCP_ELEMENTS=elements = { 9001 }\n" "still opens a loopback port" && no "AUTHORIZER_ENDPOINT=pipe: { path: /run/mediatore-gateway/check/check.sock }\nCHECK_TCP_ELEMENTS=elements = { 9001 }\n" "still opens a loopback port" && no "AUTHORIZER_ENDPOINT=socket_address: { address: 127.0.0.1, port_value: 9002 }\nCHECK_TCP_ELEMENTS=elements = { 9001 }\n" "is not .elements = { 9002 }" && no "AUTHORIZER_ENDPOINT=socket_address: { address: 0.0.0.0, port_value: 9001 }\nCHECK_TCP_ELEMENTS=elements = { 9001 }\n" "serves the tunnel check nowhere else" && no "AUTHORIZER_ENDPOINT=pipe: { path: /run/mediatore-gateway/inject/inject.sock }\n" "serves the tunnel check nowhere else" && no "AUTHORIZER_ENDPOINT=pipe: { path: /run/mediatore-gateway/check/check.sock }\nAUTHORIZER_ENDPOINT=socket_address: { address: 127.0.0.1, port_value: 9001 }\nCHECK_TCP_ELEMENTS=elements = { 9001 }\n" "still opens a loopback port" && $A check env.example vm.env.example && grep -qx "ExecStartPre=/usr/libexec/mediatore-gateway/authorizer-start check /etc/mediatore-gateway/env /etc/mediatore-gateway/vm.env" /etc/systemd/system/mediatore-gateway.service'
check "the three keys the output chain added are optional: an env file without them renders the table the example renders" \
  'cd /usr/share/mediatore-gateway && mkdir -p /tmp/r && grep -vE "^(EGRESS_DENY_ELEMENTS|CHECK_TCP_ELEMENTS|RESOLVER_ELEMENTS)=" env.example > /tmp/r/before.env && ! grep -qE "^(EGRESS_DENY_ELEMENTS|CHECK_TCP_ELEMENTS|RESOLVER_ELEMENTS)=" /tmp/r/before.env &&/usr/libexec/mediatore-gateway/render nftables.conf.in /tmp/r/before.nft /tmp/r/before.env vm.env.example && /usr/libexec/mediatore-gateway/render nftables.conf.in /tmp/r/now.nft env.example vm.env.example && cmp -s /tmp/r/before.nft /tmp/r/now.nft'
check "the example's MEDIATORE_URL names BROKER_ADDRESS at BROKER_PORT, and the authorizer's unit refuses to start when they differ (the table admits the authorizer nowhere else)" \
  'cd /usr/share/mediatore-gateway && u=$(sed -n "s/^MEDIATORE_URL=//p" env.example) && a=$(sed -n "s/^BROKER_ADDRESS=//p" env.example) && p=$(sed -n "s/^BROKER_PORT=//p" env.example) && test -n "$a" && { test "$u" = "https://$a:$p" || { test "$p" = 443 && test "$u" = "https://$a"; }; } && grep -q "^ExecStartPre=/bin/sh -c .*MEDIATORE_URL.*BROKER_ADDRESS.*exit 1" /etc/systemd/system/mediatore-gateway.service'

[ "$fail" -eq 0 ] && echo "image ok" || { echo "image check failed"; exit 1; }
